static void decoded(const machine *state, nyasm_u32 index, const nyasm_x86_span *span) {
   const nyasm_x86_detail *detail = &state->detail;
   const nyasm_u8         *bytes  = state->found.bytes + span->at;

   if (index == AT_REX) {
      field("w", bytes[0] >> 3 & 1);
      field("r", bytes[0] >> 2 & 1);
      field("x", bytes[0] >> 1 & 1);
      field("b", bytes[0] & 1);
   } else if (index == AT_MODRM) {
      field("mod", detail->modrm >> 6);
      field("reg", detail->modrm >> 3 & 7);
      field("rm", detail->modrm & 7);
   } else if (index == AT_SIB) {
      field("scale", 1u << (detail->sib >> 6));
      field("index", detail->sib >> 3 & 7);
      field("base", detail->sib & 7);
   } else if (index == AT_DISPLACEMENT) {
      printf("0x%x", detail->displacement);
   } else if (index == AT_IMMEDIATE) {
      printf("0x%llx", detail->immediate);
   } else if (index == AT_IMMEDIATE2) {
      printf("0x%x", detail->immediate2);
   } else {
      hex(bytes, span->size);
   }
}

