static void describe(const nyasm_context *context, const nyasm_x86_operand *operand, nyasm_u64 next, char *text,
                     size_t size) {
   const nyasm_x86_memory *memory = &operand->memory;
   const char             *joiner = "";
   const char             *minus  = "-";
   size_t                  at     = 0;

   text[0] = 0;
   if (operand->kind == NYASM_OPERAND_REGISTER) {
      snprintf(text, size, "%s", nyasm_register_name(context, operand->register_id));
   } else if (operand->kind == NYASM_OPERAND_MEMORY || operand->kind == NYASM_OPERAND_ADDRESS) {
      at += (size_t)snprintf(text + at, size - at, "[");
      if (memory->base) {
         at    += (size_t)snprintf(text + at, size - at, "%s", nyasm_register_name(context, memory->base));
         joiner = " + ";
         minus  = " - ";
      }

      if (memory->index) {
         at     += (size_t)snprintf(text + at, size - at, "%s%s*%u", joiner,
                                    nyasm_register_name(context, memory->index), memory->scale);
         joiner = " + ";
         minus  = " - ";
      }

      if (memory->displacement < 0) {
         at += (size_t)snprintf(text + at, size - at, "%s0x%llx", minus,
                                0ull - (unsigned long long)memory->displacement);
      } else if (!memory->displacement && !joiner[0] && operand->visibility == NYASM_VISIBILITY_SUPPRESSED) {
         at += (size_t)snprintf(text + at, size - at, "implicit");
      } else if (memory->displacement || !joiner[0]) {
         at += (size_t)snprintf(text + at, size - at, "%s0x%llx", joiner,
                                (unsigned long long)memory->displacement);
      }

      snprintf(text + at, size - at, "]");
   } else if (operand->kind == NYASM_OPERAND_RELATIVE) {
      snprintf(text, size, "0x%llx", next + operand->immediate);
   } else if (operand->kind == NYASM_OPERAND_IMMEDIATE || operand->kind == NYASM_OPERAND_POINTER) {
      snprintf(text, size, "0x%llx", operand->immediate);
   }
}

static void gather(machine *state) {
   nyasm_x86_operand *operand;
   nyasm_u64          next  = state->address + state->found.length;
   nyasm_u32          count = nyasm_operand_count(state->context, state->found.handle);
   nyasm_u32          index;

   state->count = 0;
   for (index = 0; index < count && state->count < NYASM_X86_OPERAND_LIMIT; ++index) {
      operand = state->operands + state->count;
      nyasm_x86_decode_l3(state->context, &state->found, index, operand);
      if (!(operand->flags & NYASM_OPERAND_FLAG_PART)) {
         describe(state->context, operand, next, state->texts[state->count], TEXT);
         ++state->count;
      }
   }
}

